    @Test
    /**
     * Full Create-Read-Update-Delete of a Observation, through a ObservationTest.
     */
    public void testCRUD() throws Throwable {
    try {
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "Beginning full test on ObservationTest..." );

        testCreate();
        testRead();
        testUpdate();
        testGetAll();
        testDelete();

        LOGGER.info( "Successfully ran a full test on ObservationTest..." );
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "" );
    }
    catch( Throwable e ) {
        throw e;
    }
    finally  {
        if ( handler != null ) {
            handler.flush();
            LOGGER.removeHandler(handler);
        }
    }
}

    /**
     * Tests creating a new Observation.
     *
     * @return    Observation
     */
    public Observation testCreate() throws Throwable {
    Observation entity = null;

    LOGGER.info( "ObservationTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Observation");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Observation" );

    try {
        entity = service.createObservation( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getObservationId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Observation with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Observation.
     *
     * @return    Observation
     */
    public Observation testRead() throws Throwable {
    LOGGER.info( "ObservationTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Observation" );

    Observation entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Observation with primary key" );
    msg.append( theId );

    try {
        entity = service.getObservation( new ObservationFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getObservationId();

        LOGGER.info( "-- Successfully found Observation " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Observation.
     *
     * @return    Observation
     */
    public Observation testUpdate() throws Throwable {
    LOGGER.info( "ObservationTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Observation." );

    StringBuilder msg = new StringBuilder( "Failed to update a Observation : " );
    Observation entity = null;

    try {
        UpdateObservationCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setObservationId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Observation." );

        entity = service.updateObservation( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Observation - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Observation.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "ObservationTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Observation." );

    try {
        DeleteObservationCommand deleteCommand = new DeleteObservationCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Observation with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Observation with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Observations.
     *
     * @return    Collection
     */
    public List<Observation> testGetAll() throws Throwable {
    LOGGER.info( "ObservationTest:testGetAll() - Retrieving Collection of Observations:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Observation : " );
    List<Observation> collection  = null;

    try {
        // call the static get method on the ObservationService
        collection = service.getAllObservation();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Observation currEntity  = null;
            Iterator<Observation> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getObservationId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

    public ObservationTest setHandler( Handler handler ) {
    this.handler = handler;
    LOGGER.addHandler(handler);	// assign so the LOGGER can only output results to the Handler
    return this;
}


